CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY,contact text UNIQUE NOT NULL,display_name text NOT NULL,permission_revision int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contexts(id uuid PRIMARY KEY,kind text NOT NULL CHECK(kind IN('personal','organization','carrier','seller','platform')),label text NOT NULL);
CREATE TABLE IF NOT EXISTS memberships(user_id uuid REFERENCES users(id),context_id uuid REFERENCES contexts(id),roles text[] NOT NULL,permissions text[] NOT NULL,active boolean NOT NULL DEFAULT true,version int NOT NULL DEFAULT 1,PRIMARY KEY(user_id,context_id));
CREATE TABLE IF NOT EXISTS otp_challenges(id uuid PRIMARY KEY,user_id uuid REFERENCES users(id),contact_hash text NOT NULL,code_hash text NOT NULL,expires_at timestamptz NOT NULL,attempts int NOT NULL DEFAULT 0,consumed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS otp_contact_rate ON otp_challenges(contact_hash,created_at DESC);
CREATE TABLE IF NOT EXISTS sessions(id uuid PRIMARY KEY,token_hash text UNIQUE NOT NULL,user_id uuid NOT NULL REFERENCES users(id),context_id uuid NOT NULL REFERENCES contexts(id),csrf_hash text NOT NULL,csrf_token text NOT NULL,permission_revision int NOT NULL,expires_at timestamptz NOT NULL,step_up_until timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS feature_controls(key text PRIMARY KEY,enabled boolean NOT NULL,revision int NOT NULL DEFAULT 1,mandatory boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS feature_proposals(id uuid PRIMARY KEY,key text NOT NULL,enabled boolean NOT NULL,maker_id uuid NOT NULL,expected_revision int NOT NULL,reason text NOT NULL,state text NOT NULL DEFAULT 'proposed',checker_id uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit(id uuid PRIMARY KEY,actor_id uuid,tenant_id uuid NOT NULL,action text NOT NULL,resource_id uuid,reason text NOT NULL DEFAULT '',data jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_scope ON audit(tenant_id,created_at DESC,id);
CREATE TABLE IF NOT EXISTS orders(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,owner_id uuid NOT NULL,product_id text NOT NULL,carrier_id text NOT NULL,state text NOT NULL CHECK(state IN('awaiting_payment','committed','cancelled')),payment_state text NOT NULL CHECK(payment_state IN('pending','verified','credit')),issuance_state text NOT NULL CHECK(issuance_state IN('not_started','pending','issued','failed','external_outcome_unknown')),quote_snapshot jsonb NOT NULL,version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),committed_at timestamptz);
CREATE INDEX IF NOT EXISTS order_owner ON orders(tenant_id,owner_id,created_at DESC,id);
ALTER TABLE users ADD COLUMN IF NOT EXISTS mfa_secret text;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS exception_code text;
CREATE TABLE IF NOT EXISTS payment_attempts(id uuid PRIMARY KEY,order_id uuid NOT NULL REFERENCES orders(id),provider_ref text UNIQUE NOT NULL,amount numeric(24,0) NOT NULL CHECK(amount>0),state text NOT NULL CHECK(state IN('pending','verified','failed','external_outcome_unknown')),provider_confirmed boolean NOT NULL DEFAULT false,verified_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payment_receipts(id uuid PRIMARY KEY,attempt_id uuid NOT NULL UNIQUE REFERENCES payment_attempts(id),provider_ref text NOT NULL UNIQUE,amount numeric(24,0) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS journals(id uuid PRIMARY KEY,source_key text NOT NULL UNIQUE,currency text NOT NULL CHECK(currency='IRR'),description text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS postings(id uuid PRIMARY KEY,journal_id uuid NOT NULL REFERENCES journals(id),tenant_id uuid NOT NULL,account text NOT NULL,amount numeric(24,0) NOT NULL CHECK(amount<>0));
CREATE OR REPLACE FUNCTION enforce_balanced_journal() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (SELECT COALESCE(sum(amount),0) FROM postings WHERE journal_id=NEW.journal_id)<>0 THEN RAISE EXCEPTION 'unbalanced journal'; END IF; RETURN NULL; END $$;
DROP TRIGGER IF EXISTS journal_balance ON postings;
CREATE CONSTRAINT TRIGGER journal_balance AFTER INSERT OR UPDATE ON postings DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION enforce_balanced_journal();
CREATE OR REPLACE FUNCTION reject_ledger_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'ledger is append-only'; END $$;
DROP TRIGGER IF EXISTS postings_immutable ON postings;
CREATE TRIGGER postings_immutable BEFORE UPDATE OR DELETE ON postings FOR EACH ROW EXECUTE FUNCTION reject_ledger_mutation();
DROP TRIGGER IF EXISTS journals_immutable ON journals;
CREATE TRIGGER journals_immutable BEFORE UPDATE OR DELETE ON journals FOR EACH ROW EXECUTE FUNCTION reject_ledger_mutation();
CREATE TABLE IF NOT EXISTS idempotency(scope text NOT NULL,operation text NOT NULL,key text NOT NULL,digest text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(scope,operation,key));
CREATE TABLE IF NOT EXISTS outbox(id uuid PRIMARY KEY,event_type text NOT NULL,aggregate_id uuid NOT NULL,tenant_id uuid NOT NULL,payload jsonb NOT NULL,state text NOT NULL DEFAULT 'pending' CHECK(state IN('pending','processing','delivered','dead','unknown')),attempts int NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),locked_until timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),last_error text);
CREATE INDEX IF NOT EXISTS outbox_ready ON outbox(next_attempt_at,created_at) WHERE state IN('pending','processing');
CREATE TABLE IF NOT EXISTS submissions(id uuid PRIMARY KEY,order_id uuid NOT NULL UNIQUE REFERENCES orders(id),carrier_id text NOT NULL,external_ref text,state text NOT NULL CHECK(state IN('pending','sending','acknowledged','issued','rejected','external_outcome_unknown')),policy_id uuid,version int NOT NULL DEFAULT 1,data jsonb NOT NULL DEFAULT '{}',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS policies(id uuid PRIMARY KEY,order_id uuid NOT NULL UNIQUE REFERENCES orders(id),tenant_id uuid NOT NULL,owner_id uuid NOT NULL,carrier_id text NOT NULL,reference text NOT NULL,effective_from date NOT NULL,effective_until date NOT NULL,state text NOT NULL,document_key text,data jsonb NOT NULL DEFAULT '{}',version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(carrier_id,reference));
CREATE INDEX IF NOT EXISTS policy_owner ON policies(tenant_id,owner_id,created_at DESC,id);
CREATE TABLE IF NOT EXISTS inbox(id uuid PRIMARY KEY,source text NOT NULL,external_event_id text NOT NULL,payload_digest text NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),UNIQUE(source,external_event_id));
CREATE TABLE IF NOT EXISTS credit_accounts(tenant_id uuid PRIMARY KEY,credit_limit numeric(24,0) NOT NULL CHECK(credit_limit>=0),reserved numeric(24,0) NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=credit_limit));
CREATE TABLE IF NOT EXISTS credit_approvals(id uuid PRIMARY KEY,order_id uuid NOT NULL UNIQUE REFERENCES orders(id),maker_id uuid NOT NULL,checker_id uuid,amount numeric(24,0) NOT NULL CHECK(amount>0),state text NOT NULL DEFAULT 'requested',reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS refunds(id uuid PRIMARY KEY,order_id uuid NOT NULL REFERENCES orders(id),amount numeric(24,0) NOT NULL CHECK(amount>0),maker_id uuid NOT NULL,checker_id uuid,state text NOT NULL CHECK(state IN('requested','approved','paid','rejected','external_outcome_unknown')),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
